{
  "id": "R1",
  "summary_ko": "현수막을 들고 있어야 하는 사람 뒤로 현수막이 사라짐.",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "banners disappear behind the person that supposed to be holding it",
      "symptom_ko": "현수막을 들고 있어야 하는 사람 뒤로 현수막이 사라진다.",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "banners",
      "explicit_detail_evidence": [
        "disappear behind the person that supposed to be holding it"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "사람들이 착용한 선글라스가 얼굴에서 사라졌다 나타남",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "sunglasses on people disappear and appear on the face",
      "symptom_ko": "얼굴 위의 선글라스가 사라졌다가 다시 나타남",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "sunglasses on people",
      "explicit_detail_evidence": [
        "disappear and appear on the face"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R3",
  "summary_ko": "사람들이 들고 있던 깃발이 그들이 카메라 쪽으로 달릴 때 뒤에 떠서 따라온다.",
  "claims": [
    {
      "id": "R3.S1",
      "evidence": "The flags that the people were holding are floating behind and follow them as they run towards the camera.",
      "symptom_ko": "사람들이 들고 있던 깃발이 손에서 분리되어 뒤쪽에 뜬 채로 따라온다.",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "The flags that the people were holding",
      "explicit_detail_evidence": [
        "floating behind and follow them"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "target_relation": "different",
      "reference_claim_ids": ["R1.S1"],
      "reference_evidence": "banners disappear behind the person that supposed to be holding it",
      "candidate_evidence": "배경에 울타리가 있어야 하나 나무와 잔디만 확인됨",
      "basis": "explicit_separation",
      "reason_ko": "참조 설명은 사람이 들고 있어야 할 현수막(banners)이 사라지는 현상을 다루고 있으며, 후보 설명은 배경의 울타리(fence)가 누락된 결함을 기술하고 있어 대상 엔티티와 결함 내용이 완전히 분리된 별개의 현상입니다."
    }
  ]
}

